class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        score = 0
        # Sort each row in descending order
        for row in nums:
            row.sort(reverse=True)

        # Iterate over each column
        for i in range(len(nums[0])):
            current_max = 0
            # Check each row for the element at position i
            for row in nums:
                if i < len(row):
                    if row[i] > current_max:
                        current_max = row[i]
            score += current_max

        return score

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        suffix = [0] * (n + 1)

        for i in range(n):
            prefix[i + 1] = prefix[i] | nums[i]

        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] | nums[i]

        max_or = 0
        for i in range(n):
            current = nums[i] << k
            total = prefix[i] | suffix[i + 1] | current
            if total > max_or:
                max_or = total

        return max_or

from itertools import combinations

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        max_product = float('-inf')
        n = len(nums)
        for k in range(1, n+1):
            for subset in combinations(nums, k):
                product = 1
                for num in subset:
                    product *= num
                if product > max_product:
                    max_product = product
        return max_product

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1  # Initialize by assuming the current character is extra
            for word in dictionary:
                word_len = len(word)
                if i >= word_len and s[i - word_len:i] == word:
                    dp[i] = min(dp[i], dp[i - word_len])

        return dp[n]

