class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def calculate(s: str) -> int:
            n = len(s)
            memo = {}

            def dp(pos: int, tight: bool, sum_digits: int) -> int:
                if pos == n:
                    return 1 if min_sum <= sum_digits <= max_sum else 0
                key = (pos, tight, sum_digits)
                if key in memo:
                    return memo[key]

                limit = int(s[pos]) if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_sum = sum_digits + d
                    if new_sum > max_sum:
                        continue  # further digits will only increase the sum
                    res += dp(pos + 1, new_tight, new_sum)
                    res %= MOD
                memo[key] = res
                return res

            return dp(0, True, 0)

        # Compute the count for num2 and subtract the count for num1 - 1
        total = calculate(num2)
        subtract = calculate(str(int(num1) - 1)) if num1 != '1' else 0
        return (total - subtract) % MOD

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        res = []
        count = 0
        for index, color in queries:
            # Check the current color of the index
            current_color = nums[index]
            # Check left neighbor
            if index > 0:
                if current_color != 0 and nums[index - 1] == current_color:
                    count -= 1
            # Check right neighbor
            if index < n - 1:
                if current_color != 0 and nums[index + 1] == current_color:
                    count -= 1
            # Update the color
            nums[index] = color
            # Check left neighbor with new color
            if index > 0:
                if nums[index - 1] == color:
                    count += 1
            # Check right neighbor with new color
            if index < n - 1:
                if nums[index + 1] == color:
                    count += 1
            res.append(count)
        return res

class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)
        pos1 = nums.index(1)
        posn = nums.index(n)

        if pos1 < posn:
            return pos1 + (n - 1 - posn)
        else:
            return pos1 + (n - 1 - posn) - 1

class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        max_len = 1
        n = len(s)
        for i in range(n):
            consecutive_pairs = 0
            for j in range(i + 1, n):
                if s[j] == s[j - 1]:
                    consecutive_pairs += 1
                    if consecutive_pairs > 1:
                        break
                current_len = j - i + 1
                if consecutive_pairs <= 1 and current_len > max_len:
                    max_len = current_len
        return max_len

class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        received = set()
        current = 1  # starts with friend 1
        received.add(current)
        step = 1

        while True:
            next_friend = (current + step * k) % n
            if next_friend == 0:
                next_friend = n
            else:
                next_friend = next_friend
            if next_friend in received:
                break
            received.add(next_friend)
            current = next_friend
            step += 1

        losers = []
        for friend in range(1, n+1):
            if friend not in received:
                losers.append(friend)
        return losers

class Solution:
    def doesValidArrayExist(self, derived: List[int]) -> bool:
        n = len(derived)
        for first in [0, 1]:
            original = [0] * n
            original[0] = first
            for i in range(n - 1):
                original[i + 1] = original[i] ^ derived[i]
            if (original[-1] ^ original[0]) == derived[-1]:
                return True
        return False

