class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s, target):
            if not s:
                return target == 0
            for i in range(1, len(s) + 1):
                current = int(s[:i])
                remaining = s[i:]
                if can_partition(remaining, target - current):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            square = i * i
            if can_partition(str(square), i):
                total += square
        return total

class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        res = float('inf')
        # We will keep track of the minimum cost for each position after up to k rotations
        min_cost = nums.copy()

        for k in range(n):
            total = sum(min_cost) + k * x
            if total < res:
                res = total
            # Update min_cost for the next rotation
            for i in range(n):
                # The cost for position i after k+1 rotations is nums[(i - (k+1)) mod n]
                # But for the next iteration, we can compare with the current min_cost[i]
                candidate = nums[(i - (k + 1)) % n]
                if candidate < min_cost[i]:
                    min_cost[i] = candidate
        return res

class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        result = []
        forbidden = set()
        num = 1

        while len(result) < n:
            if num not in forbidden:
                result.append(num)
                if k - num > num:  # Ensure we don't add duplicates and only positive numbers
                    forbidden.add(k - num)
            num += 1

        return sum(result)

