class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        max_num = max(nums)
        spf = [0] * (max_num + 1)
        for i in range(2, max_num + 1):
            if spf[i] == 0:
                spf[i] = i
                for j in range(i * i, max_num + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

        def get_prime_factors(x):
            factors = set()
            if x == 1:
                return factors
            while x > 1:
                p = spf[x]
                factors.add(p)
                while x % p == 0:
                    x = x // p
            return factors

        parent = list(range(len(nums)))
        rank = [1] * len(nums)

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            u_root = find(u)
            v_root = find(v)
            if u_root == v_root:
                return
            if rank[u_root] > rank[v_root]:
                parent[v_root] = u_root
                rank[u_root] += rank[v_root]
            else:
                parent[u_root] = v_root
                rank[v_root] += rank[u_root]

        prime_to_index = {}

        for i, num in enumerate(nums):
            if num == 1:
                return False
            primes = get_prime_factors(num)
            for p in primes:
                if p in prime_to_index:
                    union(i, prime_to_index[p])
                else:
                    prime_to_index[p] = i

        root = find(0)
        return all(find(i) == root for i in range(len(nums)))

class Solution:
    def smallestString(self, s: str) -> str:
        s_list = list(s)
        n = len(s_list)
        i = 0

        # Find the first non 'a' character
        while i < n and s_list[i] == 'a':
            i += 1

        # If all characters are 'a', replace the last 'a' with 'z'
        if i == n:
            s_list[-1] = 'z'
            return ''.join(s_list)

        # Replace from i to the next 'a' or end of string
        j = i
        while j < n and s_list[j] != 'a':
            s_list[j] = chr(ord(s_list[j]) - 1)
            j += 1

        return ''.join(s_list)

