class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        count = 0
        n = len(nums)
        for i in range(n):
            first_digit = nums[i]
            while first_digit >= 10:
                first_digit //= 10
            for j in range(i + 1, n):
                last_digit = nums[j] % 10
                if math.gcd(first_digit, last_digit) == 1:
