class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [-1] * n
        dp[0] = 0  # starting point, 0 jumps

        for i in range(1, n):
            for j in range(i):
                if abs(nums[i] - nums[j]) <= target and dp[j] != -1:
                    if dp[i] < dp[j] + 1:
                        dp[i] = dp[j] + 1
        return dp[-1] if dp[-1] != -1 else -1

