class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        max_length = 0
        n = len(nums)

        for l in range(n):
            if nums[l] % 2 == 0 and nums[l] <= threshold:
                current_length = 1
                max_length = max(max_length, current_length)
                for r in range(l + 1, n):
                    if nums[r] > threshold:
                        break
                    if nums[r - 1] % 2 == nums[r] % 2:
                        break
                    current_length += 1
                    max_length = max(max_length, current_length)

        return max_length

class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        ones_indices = [i for i, num in enumerate(nums) if num == 1]

        if not ones_indices:
            return 0

        total = 1
        for i in range(1, len(ones_indices)):
            diff = ones_indices[i] - ones_indices[i-1]
            total = (total * diff) % MOD

        return total

from collections import deque

class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        left = 0
        res = 0
        min_deque = deque()
        max_deque = deque()

        for right, num in enumerate(nums):
            # Maintain the min deque: elements are in increasing order
            while min_deque and nums[min_deque[-1]] >= num:
                min_deque.pop()
            min_deque.append(right)

            # Maintain the max deque: elements are in decreasing order
            while max_deque and nums[max_deque[-1]] <= num:
                max_deque.pop()
            max_deque.append(right)

            # Ensure the current window meets the condition: max - min <= 2
            while nums[max_deque[0]] - nums[min_deque[0]] > 2:
                left += 1
                # Remove indices from deques that are outside the current window
                while min_deque[0] < left:
                    min_deque.popleft()
                while max_deque[0] < left:
                    max_deque.popleft()

            res += right - left + 1

        return res

class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        if n == 0:
            return 0

        dp1 = 1  # ending with nums1[i]
        dp2 = 1  # ending with nums2[i]
        max_len = 1

        for i in range(1, n):
            new_dp1 = 1
            new_dp2 = 1

            if nums1[i] >= nums1[i-1]:
                new_dp1 = max(new_dp1, dp1 + 1)
            if nums1[i] >= nums2[i-1]:
                new_dp1 = max(new_dp1, dp2 + 1)

            if nums2[i] >= nums1[i-1]:
                new_dp2 = max(new_dp2, dp1 + 1)
            if nums2[i] >= nums2[i-1]:
                new_dp2 = max(new_dp2, dp2 + 1)

            dp1, dp2 = new_dp1, new_dp2
            max_len = max(max_len, dp1, dp2)

        return max_len

class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        max_len = -1
        n = len(nums)

        for i in range(n - 1):
            if nums[i + 1] == nums[i] + 1:
                current_len = 2
                # Determine the expected next value
                expected_change = -1  # because after +1, next should be -1
                for j in range(i + 2, n):
                    if nums[j] == nums[j - 1] + expected_change:
                        current_len += 1
                        expected_change *= -1  # toggle between -1 and +1
                    else:
                        break
                if current_len > max_len:
                    max_len = current_len
        return max_len if max_len != -1 else -1

class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        max_val = nums[-1]
        current = nums[-1]
        for i in range(n-2, -1, -1):
            if nums[i] <= current:
                current += nums[i]
            else:
                current = nums[i]
            if current > max_val:
                max_val = current
        return max_val

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        if n < 2:
            return []

        # Sieve of Eratosthenes to find primes up to n
        sieve = [True] * (n + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if sieve[i]:
                sieve[i*i :: i] = [False] * len(sieve[i*i :: i])

        result = []
        for x in range(2, n // 2 + 1):
            y = n - x
            if y >= x and sieve[x] and sieve[y]:
                result.append([x, y])

        return result

