class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        MOD = 10**9 + 7
        # Generate all possible a_i where a_i^x <= n
        candidates = []
        i = 1
        while True:
            power = i ** x
            if power > n:
                break
            candidates.append(power)
            i += 1

        dp = [0] * (n + 1)
        dp[0] = 1

        for num in candidates:
            for j in range(n, num - 1, -1):
                dp[j] = (dp[j] + dp[j - num]) % MOD

        return dp[n] % MOD

class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        n = len(s)
        max_num = 1 << n  # The maximum possible number is 2^n - 1, but 1 << n is 2^n which is sufficient for comparison

        # Precompute all powers of 5 that can be represented in up to n bits
        power_of_5 = set()
        num = 1  # 5^0
        while num < max_num:
            power_of_5.add(bin(num)[2:])
            num *= 5

        # Initialize DP array
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                substring = s[j:i]
                if substring[0] == '0':
                    continue
                if substring in power_of_5:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1
        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forbidden_set = set(forbidden)
        max_len_forbidden = max(len(f) for f in forbidden) if forbidden else 0
        left = 0
        max_valid = 0

        for right in range(len(word)):
            # Check all possible substrings ending at 'right' with length up to max_len_forbidden
            for length in range(1, min(max_len_forbidden, right - left + 1) + 1):
                substring = word[right - length + 1 : right + 1]
                if substring in forbidden_set:
                    left = right - length + 2  # Move left to right - length + 2 to exclude the forbidden substring
                    break
            current_length = right - left + 1
            if current_length > max_valid:
                max_valid = current_length

        return max_valid

