class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        # Initialize max scores based on first number's parity
        if nums[0] % 2 == 0:
            even_max = nums[0]
            odd_max = nums[0] - x
        else:
            odd_max = nums[0]
            even_max = nums[0] - x

        # Iterate through the array starting from position 1
        for i in range(1, len(nums)):
            if nums[i] % 2 == 0:
                # Current number is even
                # We can either continue from previous even or switch from odd
                even_max = max(even_max + nums[i], odd_max + nums[i] - x)
            else:
                # Current number is odd
                # We can either continue from previous odd or switch from even
                odd_max = max(odd_max + nums[i], even_max + nums[i] - x)

        # Return the maximum of both cases
        return max(even_max, odd_max)

