        for num in nums:
            max_digit = max(int(d) for d in str(num))
            max_digit_map[max_digit].append(num)

        max_sum = -1

        for key in max_digit_map:
            numbers = max_digit_map[key]
            if len(numbers) >= 2:
                numbers_sorted = sorted(numbers, reverse=True)
                current_sum = numbers_sorted[0] + numbers_sorted[1]
                if current_sum > max_sum:
                    max_sum = current_sum

        return max_sum

