class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7
        count = 0

        # Helper function to check if a number is in range
        def in_range(num):
            return low <= num <= high

        # BFS queue
        from collections import deque
        q = deque()

        # Initialize with single-digit numbers (1-9)
        for d in range(1, 10):
            num = str(d)
            q.append(num)
            if in_range(num):
                count += 1

        while q:
            current = q.popleft()
            last_digit = int(current[-1])

            # Generate next possible digits
            for next_digit in [last_digit - 1, last_digit + 1]:
                if 0 <= next_digit <= 9:
                    new_num = current + str(next_digit)

                    # If new_num is greater than high, we can stop
                    if new_num > high:
                        continue

                    q.append(new_num)
                    if in_range(new_num):
                        count = (count + 1) % MOD

        # Check if low is "0" (special case)
        if low == "0":
            count = (count + 1) % MOD

        return count

