class Solution:
    def minimumTime(self, nums1: List[int], nums2: List[int], x: int) -> int:
        n = len(nums1)
        pairs = sorted(zip(nums1, nums2), key=lambda x: -x[1])

        # Initialize DP array
        dp = [float('inf')] * (n + 1)
        dp[0] = sum(nums1)

        for i in range(n):
            num1, num2 = pairs[i]
            for t in range(i, -1, -1):
                if dp[t] == float('inf'):
                    continue
                # If we choose to zero out this element at time t+1
                new_sum = dp[t] - num1 - num2 * (t + 1)
                if new_sum < dp[t + 1]:
                    dp[t + 1] = new_sum

        # Find the minimum t where dp[t] <= x
        for t in range(n + 1):
            if dp[t] <= x:
                return t
        return -1

