class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        if x == 0:
            return 0

        min_diff = float('inf')
        sorted_nums = []

        # Process the array in reverse order
        for i in range(len(nums) - 1, -1, -1):
            # Add current number to sorted list
            pos = bisect_left(sorted_nums, nums[i])
            sorted_nums.insert(pos, nums[i])

            # Check elements that are at least x positions ahead
            if i + x < len(nums):
                # Find the position where nums[i+x] would be inserted
                target = nums[i + x]
                pos = bisect_left(sorted_nums, target)

                # Check the closest elements
                if pos > 0:
                    min_diff = min(min_diff, abs(target - sorted_nums[pos - 1]))
                if pos < len(sorted_nums):
                    min_diff = min(min_diff, abs(target - sorted_nums[pos]))

        return min_diff

