        i = j = 0
        n, m = len(str1), len(str2)

        while i < n and j < m:
            # Check if current character matches
            if str1[i] == str2[j]:
                i += 1
                j += 1
            else:
                # Check if next character (cyclically) matches
                next_char = chr(ord('a') + (ord(str1[i]) - ord('a') + 1) % 26)
                if next_char == str2[j]:
                    i += 1
                    j += 1
                else:
                    # Only move str1 pointer
                    i += 1

        return j == m

