class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        # Count the frequency of each power of 2 in nums
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        operations = 0
        i = 0

        # Iterate through each bit of the target
        while target > 0:
            # Get the current power of 2 we need
            current_power = 1 << i
            # Check if this bit is set in the target
            if target & current_power:
                # If we have this power available, use it
                if freq.get(current_power, 0) > 0:
                    freq[current_power] -= 1
                else:
                    # Try to find a larger power to split
                    found = False
                    for power in sorted(freq.keys()):
                        if power > current_power and freq[power] > 0:
                            # Split the larger power
                            freq[power] -= 1
                            freq[power // 2] = freq.get(power // 2, 0) + 2
                            operations += 1
                            found = True
                            break
                    if not found:
                        return -1
                    # Retry with the same power
                    continue
                # Clear this bit from the target
                target -= current_power
            i += 1

        return operations

class Solution:
    def minOperations(self, s1: str, s2: str, x: int) -> int:
        # Find all indices where s1 and s2 differ
        diffs = [i for i in range(len(s1)) if s1[i] != s2[i]]

        # If the number of differing positions is odd, return -1
        if len(diffs) % 2 != 0:
            return -1

        # Initialize DP array
        n = len(diffs)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(0, n, 2):
            if dp[i] == float('inf'):
                continue
            # Try pairing with next position using operation 2
            if i + 1 < n:
                cost = diffs[i+1] - diffs[i]
                dp[i+2] = min(dp[i+2], dp[i] + cost)
            # Try pairing with any position using operation 1
            for j in range(i+1, n):
                dp[j+1] = min(dp[j+1], dp[i] + x)

        return dp[n] if dp[n] != float('inf') else -1

