class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        # Check if already sorted
        if nums == sorted(nums):
            return 0

        # Find the pivot point where order breaks
        pivot = -1
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                if pivot != -1:
                    return -1  # More than one pivot
                pivot = i

        # If no pivot found, it's already sorted
        if pivot == -1:
            return 0

        # Check if the array can be sorted by shifting
        # The part after pivot should be sorted and last element < first element
        if nums[-1] > nums[0]:
            return -1

        # Calculate number of shifts needed
        # We need to move the pivot to the end
        return n - 1 - pivot

class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        min_ops = float('inf')

        # Valid pairs that make a number divisible by 25
        valid_pairs = [('0', '0'), ('2', '5'), ('5', '0'), ('7', '5')]

        # Iterate through the string to find the last occurrence of any valid pair
        for i in range(n - 1, -1, -1):
            for j in range(i - 1, -1, -1):
                if (num[j], num[i]) in valid_pairs:
                    # Calculate the number of deletions required
                    ops = (n - 1 - i) + (i - 1 - j)
                    if ops < min_ops:
                        min_ops = ops
                    break  # Since we are iterating from the end, the first valid pair is the last one

        # If no valid pair is found, we need to delete all digits except one '0'
        if min_ops == float('inf'):
            # Check if there is at least one '0' in the number
            if '0' in num:
                min_ops = n - 1
            else:
                min_ops = n  # If no '0', delete all digits to make it '0'

        return min_ops

