class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(x):
            # Remove all square factors
            i = 2
            while i * i <= x:
                while x % (i * i) == 0:
                    x //= (i * i)
                i += 1
            return x

        # Group numbers by their square-free parts
        groups = {}
        for idx, num in enumerate(nums, 1):
            sf = get_square_free(num)
            if sf not in groups:
                groups[sf] = []
            groups[sf].append(num)

        # Calculate maximum sum
        max_sum = 0
        for group in groups.values():
            if len(group) >= 1:
                current_sum = sum(group)
                if current_sum > max_sum:
                    max_sum = current_sum

        return max_sum

