            if total_and == 0:
                break

        if total_and != 0:
            return 1

        max_subarrays = 0
        current_and = (1 << 20) - 1
        for num in nums:
            current_and &= num
            if current_and == 0:
                max_subarrays += 1
                current_and = (1 << 20) - 1

        return max_subarrays

