class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        max_sum = r
        dp = [0] * (max_sum + 1)
        dp[0] = 1 + freq.get(0, 0)  # empty multiset plus any zeros

        del freq[0]  # zeros are handled separately

        for x in freq:
            cnt = freq[x]
            for i in range(max_sum, -1, -1):
                for k in range(1, cnt + 1):
                    if i - k * x >= 0:
                        dp[i] = (dp[i] + dp[i - k * x]) % MOD

        total = 0
        for i in range(l, r + 1):
            if i <= max_sum:
                total = (total + dp[i]) % MOD
        return total

