class Solution:
    def minOperations(self, nums: List[int]) -> int:
        freq = Counter(nums)
        operations = 0

        for count in freq.values():
            if count == 1:
                return -1
            # Use as many 3-element operations as possible
            operations += count // 3
            remainder = count % 3
            if remainder == 1:
                # Adjust: e.g., 4 = 2 + 2 is better than 3 + 1
                operations -= 1
                operations += 2
            elif remainder == 2:
                operations += 1

        return operations

