class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1
        frequencies = list(freq.values())

        min_freq = min(frequencies)

        for k in range(min_freq, 0, -1):
            total = 0
            for f in frequencies:
                q, r = divmod(f, k)
                if r > q:
                    total = -1
                    break
                groups = (f + k) // (k + 1)
                total += groups
            if total != -1:
                return total
        return len(frequencies)

