class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        if n == 1:
            return 0

        def calculate_swaps(swap_last: bool) -> int:
            swaps = 0
            # Determine the target maximums
            if swap_last:
                max1 = nums2[-1]
                max2 = nums1[-1]
                swaps += 1
            else:
                max1 = nums1[-1]
                max2 = nums2[-1]

            # Check all elements except the last
            for i in range(n - 1):
                val1 = nums1[i]
                val2 = nums2[i]
                # Check if current pair is acceptable without swap
                if val1 <= max1 and val2 <= max2:
                    continue
                # If not, check if swapping helps
                if val2 <= max1 and val1 <= max2:
                    swaps += 1
                else:
                    return -1
            return swaps

        # Evaluate both scenarios
        no_swap = calculate_swaps(False)
        with_swap = calculate_swaps(True)

        if no_swap == -1 and with_swap == -1:
            return -1
        elif no_swap == -1:
            return with_swap
        elif with_swap == -1:
            return no_swap
        else:
            return min(no_swap, with_swap)

