class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        from collections import defaultdict

        # Create a dictionary to store the first and last occurrence of each number
        first_occurrence = {}
        last_occurrence = {}

        for idx, num in enumerate(nums):
            if num not in first_occurrence:
                first_occurrence[num] = idx
            last_occurrence[num] = idx

        # Collect all intervals [start, end] for each number
        intervals = []
        for num in first_occurrence:
            start = first_occurrence[num]
            end = last_occurrence[num]
            intervals.append((start, end))

        # Sort intervals based on start time
        intervals.sort()

        # Merge intervals
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last_start, last_end = merged[-1]
                current_start, current_end = interval
                if current_start <= last_end:
                    # Merge them. The new interval's start is the min of starts (already sorted), end is max of ends
                    new_start = last_start
                    new_end = max(last_end, current_end)
                    merged[-1] = (new_start, new_end)
                else:
                    merged.append(interval)

        k = len(merged)
        MOD = 10**9 + 7
        return pow(2, k - 1, MOD)

