class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        def count_for_segment(s: str, chars: set) -> int:
            res = 0
            n = len(s)
            for i in range(n):
                freq = [0] * 26
                distinct = 0
                valid = True
                for j in range(i, n):
                    c = s[j]
                    if c not in chars:
                        break
                    idx = ord(c) - ord('a')
                    freq[idx] += 1
                    if freq[idx] == 1:
                        distinct += 1
                    if freq[idx] > k:
                        valid = False
                    if valid and all(f == 0 or f == k for f in freq):
                        res += 1
            return res

        total = 0
        n = len(word)
        # Generate all possible segments of adjacent characters with difference <= 2
        # There are 26 possible starting points, each can form segments of length 1 to 26
        for start in range(26):
            for length in range(1, 27):
                end = start + length - 1
                if end >= 26:
                    continue
                # Check if the segment is valid (each adjacent char differs by at most 2)
                valid_segment = True
                for i in range(start, end):
                    if (i + 1) - i > 2:
                        valid_segment = False
                        break
                if not valid_segment:
                    continue
                # Create the set of characters in this segment
                segment_chars = {chr(ord('a') + c) for c in range(start, end + 1)}
                total += count_for_segment(word, segment_chars)
        return total

