class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)
        max_partitions = 0

        # Function to calculate partitions without any changes
        def calculate_partitions(s):
            partitions = 0
            i = 0
            while i < len(s):
                distinct = set()
                j = i
                while j < len(s):
                    distinct.add(s[j])
                    if len(distinct) > k:
                        break
                    j += 1
                partitions += 1
                i = j
            return partitions

        max_partitions = calculate_partitions(s)

        # Try changing each character to every possible other character and check partitions
        for i in range(n):
            original_char = s[i]
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c == original_char:
                    continue
                new_s = s[:i] + c + s[i+1:]
                current_partitions = calculate_partitions(new_s)
                if current_partitions > max_partitions:
                    max_partitions = current_partitions
        return max_partitions

