import sys

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Initialize the distance matrix with infinity
        size = 26
        dist = [[sys.maxsize] * size for _ in range(size)]
        for i in range(size):
            dist[i][i] = 0

        # Populate the direct edges
        for o, c, co in zip(original, changed, cost):
            u = ord(o) - ord('a')
            v = ord(c) - ord('a')
            if dist[u][v] > co:
                dist[u][v] = co

        # Floyd-Warshall algorithm to find all pairs shortest paths
        for k in range(size):
            for i in range(size):
                for j in range(size):
                    if dist[i][k] != sys.maxsize and dist[k][j] != sys.maxsize:
                        if dist[i][j] > dist[i][k] + dist[k][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

        total_cost = 0
        for s_char, t_char in zip(source, target):
            if s_char == t_char:
                continue
            u = ord(s_char) - ord('a')
            v = ord(t_char) - ord('a')
            if dist[u][v] == sys.maxsize:
                return -1
            total_cost += dist[u][v]

        return total_cost

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        if not nums:
            return 0

        # Step 1: Find the longest sequential prefix
        prefix = [nums[0]]
        for i in range(1, len(nums)):
            if nums[i] == nums[i-1] + 1:
                prefix.append(nums[i])
            else:
                break

        # Step 2: Calculate the sum of the prefix
        sum_prefix = sum(prefix)

        # Step 3: Find the smallest missing integer >= sum_prefix not in nums
        nums_set = set(nums)
        x = sum_prefix
        while x in nums_set:
            x += 1
        return x

