class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque()
        queue.append((x, 0))
        visited = set()
        visited.add(x)

        while queue:
            current, ops = queue.popleft()

            if current == y:
                return ops

            next_steps = []
            # Generate all possible next steps
            if current % 11 == 0:
                next_steps.append(current // 11)
            if current % 5 == 0:
                next_steps.append(current // 5)
            next_steps.append(current + 1)
            next_steps.append(current - 1)

            for next_val in next_steps:
                if next_val == y:
                    return ops + 1
                if next_val not in visited and next_val <= 10**4 + 100 and next_val >= 0:
                    visited.add(next_val)
                    queue.append((next_val, ops + 1))

        return -1  # should theoretically never reach here for given constraints

