class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        a_indices = []
        b_indices = []
        len_a = len(a)
        len_b = len(b)
        len_s = len(s)

        # Collect all starting indices where a is found in s
        for i in range(len_s - len_a + 1):
            if s[i:i+len_a] == a:
                a_indices.append(i)

        # Collect all starting indices where b is found in s
        for j in range(len_s - len_b + 1):
            if s[j:j+len_b] == b:
                b_indices.append(j)

        beautiful = []
        if not b_indices:
            return beautiful

        for i in a_indices:
            left = i - k
            right = i + k
            # Find the first j >= left
            pos = bisect.bisect_left(b_indices, left)
            if pos < len(b_indices):
                j = b_indices[pos]
                if j <= right:
                    beautiful.append(i)

        return beautiful

