class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        for i in range(n):
            for j in range(i, n):
                # Check if nums[0..i-1] is strictly increasing
                left_valid = True
                for k in range(1, i):
                    if nums[k] <= nums[k-1]:
                        left_valid = False
                        break
                if not left_valid:
                    continue

                # Check if nums[j+1..n-1] is strictly increasing
                right_valid = True
                for k in range(j+2, n):
                    if nums[k] <= nums[k-1]:
                        right_valid = False
                        break
                if not right_valid:
                    continue

                # Check if the last of left (if exists) is less than first of right (if exists)
                last_left = nums[i-1] if i > 0 else None
                first_right = nums[j+1] if j < n-1 else None

                if last_left is not None and first_right is not None:
                    if last_left >= first_right:
                        continue
                count += 1
        return count

class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        res = 0
        for bit in range(29, -1, -1):
            mask = 1 << bit
            res_mask = res | mask
            count = 0
            current_and = (1 << 30) - 1  # Initialize to all ones
            for num in nums:
                current_and &= num
                if (current_and & res_mask) == 0:
                    count += 1
                    current_and = (1 << 30) - 1  # reset to all ones
            if count > k:
                res |= mask
        return res

