class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        set_bits = [bin(num).count('1') for num in nums]

        groups = []
        current_group = [nums[0]]
        current_set_bits = set_bits[0]

        for i in range(1, n):
            if set_bits[i] == current_set_bits:
                current_group.append(nums[i])
            else:
                groups.append(current_group)
                current_group = [nums[i]]
                current_set_bits = set_bits[i]
        groups.append(current_group)

        group_info = []
        for group in groups:
            if not group:
                continue
            group_min = min(group)
            group_max = max(group)
            group_info.append((group_min, group_max))

        for i in range(len(group_info) - 1):
            if group_info[i][1] > group_info[i+1][0]:
                return False

        return True

