class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        left = 1
        right = m
        answer = -1

        def is_possible(s):
            last_pos = {}
            for second in range(s):
                idx = changeIndices[second] - 1  # converting to 0-based
                last_pos[idx] = second  # this will keep updating to the last occurrence for each index

            if len(last_pos) != n:
                return False

            total_operations = 0
            marked = 0
            for second in range(s):
                idx = changeIndices[second] - 1
                if second == last_pos[idx]:
                    if nums[idx] > (second - marked):
                        return False
                    marked += 1
                    total_operations += nums[idx]
                else:
                    if total_operations < second:
                        total_operations += 1
            return True

        while left <= right:
            mid = (left + right) // 2
            if is_possible(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1
        return answer

