class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        max_len = 1  # at least one element can be chosen

        for num in freq:
            if num == 1:
                continue  # handle 1 separately
            current = num
            steps = 0
            while True:
                next_num = current * current
                if freq.get(current, 0) >= 2 and next_num in freq:
                    steps += 1
                    current = next_num
                else:
                    break
            # The central element can have freq >=1, others >=2
            # Total length is 2*steps + 1
            # But need to check the central element's frequency
            central_freq = freq.get(current, 0)
            if central_freq >= 1:
                current_len = 2 * steps + 1
                if current_len > max_len:
                    max_len = current_len
            else:
                # Can't form the full sequence, steps-1
                if steps >= 1:
                    current_len = 2 * (steps - 1) + 1
                    if current_len > max_len:
                        max_len = current_len

        # Handle 1 separately
        if 1 in freq:
            ones = freq[1]
            if ones % 2 == 1:
                current_len = ones
            else:
                current_len = ones - 1
            if current_len > max_len:
                max_len = current_len

        return max_len

import heapq

class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        marked = [False] * n
        total_sum = sum(nums)
        min_heap = []

        for i in range(n):
            heapq.heappush(min_heap, (nums[i], i))

        res = []

        for index, k in queries:
            if not marked[index]:
                marked[index] = True
                total_sum -= nums[index]

            marked_count = 0
            temp = []

            while min_heap and marked_count < k:
                val, i = heapq.heappop(min_heap)
                if not marked[i]:
                    marked[i] = True
                    total_sum -= val
                    marked_count += 1
                else:
                    temp.append((val, i))

            for val, i in temp:
                heapq.heappush(min_heap, (val, i))

            res.append(total_sum)

        return res

