class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        total = 0
        for subsequence in itertools.combinations(nums, k):
            sorted_sub = sorted(subsequence)
            min_diff = float('inf')
            for i in range(len(sorted_sub) - 1):
                diff = abs(sorted_sub[i+1] - sorted_sub[i])
                if diff < min_diff:
                    min_diff = diff
            total += min_diff
        return total % MOD

