class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        id_counts = collections.defaultdict(int)
        frequency_counts = collections.defaultdict(int)
        current_max = 0
        ans = []

        for num, delta in zip(nums, freq):
            old_count = id_counts[num]
            new_count = old_count + delta
            id_counts[num] = new_count

            if old_count > 0:
                frequency_counts[old_count] -= 1
                if frequency_counts[old_count] == 0:
                    del frequency_counts[old_count]
                    if old_count == current_max:
                        current_max = max(frequency_counts.keys()) if frequency_counts else 0

            if new_count > 0:
                frequency_counts[new_count] += 1
                if new_count > current_max:
                    current_max = new_count

            ans.append(current_max if current_max != 0 else 0)

        return ans

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)

        # dp[i][j] represents the minimal sum for first i nums and first j andValues
        dp = [[float('inf')] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(1, m + 1):
                current_and = nums[i-1]
                # We need to find k such that the AND of nums[k..i-1] is andValues[j-1]
                # Iterate backwards from i-1 to 0 to compute the AND incrementally
                for k in range(i-1, -1, -1):
                    current_and &= nums[k]
                    if current_and == andValues[j-1]:
                        if dp[k][j-1] != float('inf'):
                            dp[i][j] = min(dp[i][j], dp[k][j-1] + nums[i-1])
                    elif current_and < andValues[j-1]:
                        # Since AND can only decrease, further k's will not help
                        break

        return dp[n][m] if dp[n][m] != float('inf') else -1

