class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        rows = len(grid)
        cols = len(grid[0])

        row_counts = [0] * rows
        col_counts = [0] * cols

        # Calculate row_counts and col_counts
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    row_counts[i] += 1
                    col_counts[j] += 1

        total = 0

        # Iterate through each cell to count triangles where grid[i][j] is the right angle
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    row_ones = row_counts[i] - 1
                    col_ones = col_counts[j] - 1
                    total += row_ones * col_ones

        return total

class Solution:
    def minEnd(self, n: int, x: int) -> int:
        n -= 1
        res = x
        mask = 1
        while n > 0:
            if (x & mask) == 0:
                res |= (n & 1) * mask
                n >>= 1
            mask <<= 1
        return res

