class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        dp = [float('inf')] * n
        dp[0] = 1

        for i in range(1, n):
            for j in range(i, -1, -1):
                freq = {}
                for c in s[j:i+1]:
                    freq[c] = freq.get(c, 0) + 1
                frequencies = list(freq.values())
                if all(f == frequencies[0] for f in frequencies):
                    if j == 0:
                        dp[i] = 1
                    else:
                        if dp[j-1] + 1 < dp[i]:
                            dp[i] = dp[j-1] + 1
            if dp[i] == float('inf'):
                dp[i] = dp[i-1] + 1

        return dp[-1]

class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        # We'll use a 4-dimensional DP: dp[i][j][last][streak]
        # i: number of zeros used, j: number of ones used
        # last: 0 or 1, the last character in the sequence
        # streak: current number of consecutive last characters (1..limit)
        dp = [[[[0] * (limit + 1) for _ in range(2)] for __ in range(one + 1)] for ___ in range(zero + 1)]

        # Initialize the DP with sequences of length 1
        if zero >= 1:
            dp[1][0][0][1] = 1
        if one >= 1:
            dp[0][1][1][1] = 1

        for i in range(zero + 1):
            for j in range(one + 1):
                for last in [0, 1]:
                    for streak in range(1, limit + 1):
                        current = dp[i][j][last][streak]
                        if current == 0:
                            continue
                        # Try to add a 0
                        if last == 0:
                            if streak < limit and i + 1 <= zero:
                                dp[i+1][j][0][streak + 1] = (dp[i+1][j][0][streak + 1] + current) % MOD
                        else:
                            if i + 1 <= zero:
                                dp[i+1][j][0][1] = (dp[i+1][j][0][1] + current) % MOD
                        # Try to add a 1
                        if last == 1:
                            if streak < limit and j + 1 <= one:
                                dp[i][j+1][1][streak + 1] = (dp[i][j+1][1][streak + 1] + current) % MOD
                        else:
                            if j + 1 <= one:
                                dp[i][j+1][1][1] = (dp[i][j+1][1][1] + current) % MOD

        # Sum all possible valid end states
        total = 0
        for last in [0, 1]:
            for streak in range(1, limit + 1):
                total = (total + dp[zero][one][last][streak]) % MOD
        return total

