class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def count_set_bits_up_to_n(n):
            if n == 0:
                return 0
            x = 0
            while (1 << (x + 1)) <= n:
                x += 1
            res = x * (1 << (x - 1)) + (n - (1 << x) + 1) + count_set_bits_up_to_n(n - (1 << x))
            return res

        def find_kth_element_pos(k):
            low = 0
            high = 1
            while count_set_bits_up_to_n(high) < k:
                high *= 2
            left = 0
            right = high
            while left < right:
                mid = (left + right) // 2
                if count_set_bits_up_to_n(mid) < k:
                    left = mid + 1
                else:
                    right = mid
            n = left
            prev_count = count_set_bits_up_to_n(n - 1)
            remaining = k - prev_count - 1
            bits = []
            temp = n
            while temp > 0:
                bits.append(temp & -temp)
                temp -= temp & -temp
            bits.sort()
            return bits[remaining]

        def compute_product(l, r, mod):
            product = 1
            for k in range(l, r + 1):
                element = find_kth_element_pos(k)
                product = (product * element) % mod
            return product

        results = []
        for query in queries:
            from_i, to_i, mod_i = query
            product = 1
            for k in range(from_i, to_i + 1):
                element = find_kth_element_pos(k)
                product = (product * element) % mod_i
            results.append(product)
        return results

