        return total

class Solution:
    def waysToReachStair(self, k: int) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(current_stair, jump, last_was_down):
            if current_stair == k:
                # If we reach the target stair, we count this as a valid way
                # and continue exploring other possibilities
                count = 1
            else:
                count = 0

            # Option 1: Go down to current_stair - 1
            if current_stair > 0 and not last_was_down:
                count += dfs(current_stair - 1, jump, True)

            # Option 2: Go up to current_stair + 2^jump
            count += dfs(current_stair + (1 << jump), jump + 1, False)

            return count

        # Start from stair 1, with jump = 0, and last operation was not a down
        return dfs(1, 0, False)

