class Solution:
    def compressedString(self, word: str) -> str:
        comp = []
        i = 0
        n = len(word)
        while i < n:
            current_char = word[i]
            j = i
            while j < n and word[j] == current_char and (j - i) < 9:
                j += 1
            length = j - i
            comp.append(f"{length}{current_char}")
            i = j
        return ''.join(comp)

