from collections import deque

def main():
    H, W, T = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    # Find S, G, and all o's
    points = []
    start = (-1, -1)
    goal = (-1, -1)
    candies = []
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                start = (i, j)
            elif c == 'G':
                goal = (i, j)
            elif c == 'o':
                candies.append((i, j))
    points = [start] + candies + [goal]
    N = len(points)  # S, o's..., G

    # Precompute distance between all points
    dist = [[-1]*N for _ in range(N)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(N):
        si, sj = points[i]
        q = deque()
        q.append((si, sj))
        d = [[-1]*W for _ in range(H)]
        d[si][sj] = 0
        while q:
            x, y = q.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] != '#' and d[nx][ny] == -1:
                        d[nx][ny] = d[x][y] + 1
                        q.append((nx, ny))
        # Fill dist[i][j] for all j
        for j in range(N):
            xj, yj = points[j]
            dist[i][j] = d[xj][yj]

    # Check direct path from S to G
    if dist[0][N-1] != -1 and dist[0][N-1] <= T:
        max_candies = 0
    else:
        max_candies = -1

    # Now handle paths with candies. Only if there are candies.
    K = len(candies)
    if K == 0:
        if dist[0][N-1] != -1 and dist[0][N-1] <= T:
            print(0)
        else:
            print(-1)
        return

    # DP[mask][u] : minimal distance to reach u with mask (candies collected)
    INF = float('inf')
    dp = [[INF] * N for _ in range(1 << K)]
    # Start at S (index 0), mask 0
    dp[0][0] = 0

    for mask in range(1 << K):
        for u in range(N):
            if dp[mask][u] == INF:
                continue
            for v in range(N):
                if u == v:
                    continue
                if dist[u][v] == -1:
                    continue
                new_mask = mask
                if 1 <= v <= K:  # v is a candy (0 is S, K+1 is G)
                    new_mask = mask | (1 << (v - 1))
                if dp[new_mask][v] > dp[mask][u] + dist[u][v]:
                    dp[new_mask][v] = dp[mask][u] + dist[u][v]

    # Check all masks and paths ending at G (index N-1)
    max_candies_collected = -1
    for mask in range(1 << K):
        if dp[mask][N-1] <= T:
            cnt = bin(mask).count('1')
            if cnt > max_candies_collected:
                max_candies_collected = cnt

    if max_candies_collected != -1:
        print(max_candies_collected)
    else:
        if max_candies != -1:
            print(0)
        else:
            print(-1)

