def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx])
    idx += 1
    A = list(map(int, data[idx:idx+N]))
    idx += N
    S = data[idx].strip()

    # Precompute prefix counts: for each position, count of M before it with A_i 0,1,2
    prefix_m = [[0]*3 for _ in range(N+2)]
    for i in range(1, N+1):
        for k in range(3):
            prefix_m[i][k] = prefix_m[i-1][k]
        if S[i-1] == 'M':
            val = A[i-1]
            prefix_m[i][val] += 1

    # Precompute suffix counts: for each position, count of X after it with A_i 0,1,2
    suffix_x = [[0]*3 for _ in range(N+2)]
    for i in range(N-1, -1, -1):
        for k in range(3):
            suffix_x[i][k] = suffix_x[i+1][k]
        if S[i] == 'X':
            val = A[i]
            suffix_x[i][val] += 1

    total = 0

    # Define mex function for three values
    def mex(a, b, c):
        s = {a, b, c}
        m = 0
        while m in s:
            m += 1
        return m

    # Iterate through each position j where S[j] is 'E'
    for j in range(N):
        if S[j] != 'E':
            continue
        a_j = A[j]
        # For this j, look at all possible m_val and x_val combinations
        for m_val in range(3):
            count_m = prefix_m[j][m_val]  # M before j with value m_val
            if count_m == 0:
                continue
            for x_val in range(3):
                count_x = suffix_x[j+1][x_val]  # X after j with value x_val
                if count_x == 0:
                    continue
                current_mex = mex(m_val, a_j, x_val)
                total += count_m * count_x * current_mex
    print(total)

