    import sys
    input = sys.stdin.read().split()
    ptr = 0
    N, M = map(int, input[ptr:ptr+2])
    ptr +=2

    # Initialize adjacency matrix for transitive closure
    tc = [[False]*N for _ in range(N)]

    for _ in range(M):
        a, b = map(int, input[ptr:ptr+2])
        ptr +=2
        tc[a-1][b-1] = True

