    # We'll track the last global operation (0: none, 2: lower, 3: upper)
    last_global = 0
    # We'll keep a set of indices that have been modified after the last global operation
    modified_indices = set()

    for t_i, x_i, c_i in queries:
        if t_i == 1:
            x = x_i - 1  # convert to 0-based
            S[x] = c_i
            modified_indices.add(x)
        elif t_i == 2:
            last_global = 2
            modified_indices.clear()  # previous modifications are overridden
        elif t_i == 3:
            last_global = 3
            modified_indices.clear()

    if last_global == 2:
        for i in range(N):
            if i not in modified_indices:
                if S[i].isupper():
                    S[i] = S[i].lower()
    elif last_global == 3:
        for i in range(N):
            if i not in modified_indices:
                if S[i].islower():
                    S[i] = S[i].upper()

