    grid = [list(row) for row in data[2:2+H]]

    # To keep track of which cookies are removed
    removed = [[False for _ in range(W)] for _ in range(H)]

    while True:
        # Mark cookies to be removed in rows
        row_marks = set()
        for i in range(H):
            if all(removed[i][j] for j in range(W)):
                continue
            first_char = None
            all_same = True
            for j in range(W):
                if not removed[i][j]:
                    if first_char is None:
                        first_char = grid[i][j]
                    elif grid[i][j] != first_char:
                        all_same = False
                        break
            if all_same and first_char is not None:
                for j in range(W):
                    if not removed[i][j]:
                        row_marks.add((i, j))

        # Mark cookies to be removed in columns
        col_marks = set()
        for j in range(W):
            if all(removed[i][j] for i in range(H)):
                continue
            first_char = None
            all_same = True
            for i in range(H):
                if not removed[i][j]:
                    if first_char is None:
                        first_char = grid[i][j]
