    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx])
    idx += 1

    # Read the distance matrix
    D = [[0] * N for _ in range(N)]
    for i in range(N-1):
        for j in range(i+1, N):
            D[i][j] = int(data[idx])
            D[j][i] = D[i][j]
            idx += 1

    size = 1 << N
    dp = [0] * size

    for mask in range(size):
        # Find the first unmatched vertex
        i = 0
        while i < N and (mask & (1 << i)):
            i += 1
        if i >= N:
            continue
        # Try to pair i with every other unmatched vertex j > i
        for j in range(i+1, N):
            if not (mask & (1 << j)):
                new_mask = mask | (1 << i) | (1 << j)
                if dp[new_mask] < dp[mask] + D[i][j]:
                    dp[new_mask] = dp[mask] + D[i][j]

    print(max(dp))

