def main():
    import sys
    N = int(sys.stdin.readline())

    # Step 1: Find all divisors of N between 1 and 9
    divisors = []
    for j in range(1, 10):
        if N % j == 0:
            divisors.append(j)
    divisors.sort()

    # Step 2: For each i, determine s_i
    result = []
    for i in range(N + 1):
        s_i = '-'
        for j in divisors:
            if (N // j) == 0:
                continue  # avoid division by zero, though j is at least 1
            if i % (N // j) == 0:
                s_i = str(j)
                break
        result.append(s_i)

    # Step 3: Combine into the final string
    print(''.join(result))

