def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    L = list(map(int, data[2:2+N]))

    left = max(L) - 1  # to make sure left + 1 is at least max(L)
    right = sum(L) + N - 1

    def is_possible(W):
        current_line_width = 0
        lines_used = 1
        for word in L:
            if current_line_width == 0:
                # first word in line
                if word > W:
                    return False
                current_line_width = word
            else:
                # add space and word
                if current_line_width + 1 + word > W:
                    lines_used += 1
                    current_line_width = word
                    if lines_used > M:
                        return False
                else:
                    current_line_width += 1 + word
        return lines_used <= M

    # Binary search to find minimal W
    while left < right:
        mid = (left + right) // 2
        if is_possible(mid):
            right = mid
        else:
            left = mid + 1
    print(left)

