    import sys
    from itertools import permutations

    # Read input
    lines = [line.strip() for line in sys.stdin]
    polyominoes = []
    for i in range(3):
        polyomino = []
        for j in range(4):
            row = lines[i * 4 + j]
            polyomino.append(row)
        polyominoes.append(polyomino)

    # Function to get the coordinates of a polyomino
    def get_coords(polyomino):
        coords = []
        for i in range(4):
            for j in range(4):
                if polyomino[i][j] == '#':
                    coords.append((i, j))
        return coords

    # Function to rotate a polyomino 90 degrees clockwise
    def rotate(coords):
        return [(y, 3 - x) for (x, y) in coords]

    # Function to translate a polyomino to a new position
    def translate(coords, dx, dy):
        return [(x + dx, y + dy) for (x, y) in coords]

    # Function to check if a placement is valid
    def is_valid(placement):
        grid = [[False for _ in range(4)] for _ in range(4)]
        for coords in placement:
            for (x, y) in coords:
                if x < 0 or x >= 4 or y < 0 or y >= 4 or grid[x][y]:
                    return False
                grid[x][y] = True
        return all(all(row) for row in grid)

    # Generate all possible rotations for each polyomino
    all_rotations = []
    for polyomino in polyominoes:
        coords = get_coords(polyomino)
        rotations = [coords]
        for _ in range(3):
            coords = rotate(coords)
            rotations.append(coords)
        all_rotations.append(rotations)

    # Try all possible combinations of rotations and translations
    for rot1 in all_rotations[0]:
        for rot2 in all_rotations[1]:
            for rot3 in all_rotations[2]:
                # Try all possible translations for each polyomino
                for dx1 in range(-3, 4):
                    for dy1 in range(-3, 4):
                        trans1 = translate(rot1, dx1, dy1)
                        for dx2 in range(-3, 4):
                            for dy2 in range(-3, 4):
                                trans2 = translate(rot2, dx2, dy2)
                                for dx3 in range(-3, 4):
                                    for dy3 in range(-3, 4):
                                        trans3 = translate(rot3, dx3, dy3)
                                        # Check if the placement is valid
                                        if is_valid([trans1, trans2, trans3]):
                                            print("Yes")
                                            return
    print("No")

