def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0

    N = int(data[idx])
    idx += 1

    D = list(map(int, data[idx:idx+N]))
    idx += N

    L1, C1, K1 = map(int, data[idx:idx+3])
    idx +=3
    L2, C2, K2 = map(int, data[idx:idx+3])
    idx +=3

    # Initialize DP table: dp[k1][k2] = minimal cost
    INF = float('inf')
    dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
    dp[0][0] = 0

    for d in D:
        new_dp = [[INF] * (K2 + 1) for _ in range(K1 + 1)]
        # Find all possible x1 and x2 such that x1*L1 + x2*L2 >= d
        max_x1 = min(K1, (d + L1 - 1) // L1)  # ceil(d / L1)
        for x1 in range(0, max_x1 + 1):
            remaining = max(0, d - x1 * L1)
            x2 = 0 if remaining <=0 else (remaining + L2 - 1) // L2
            if x2 > K2:
                continue
            # Now, for each previous state (k1, k2), we can add x1 and x2
            for k1 in range(K1 + 1):
                for k2 in range(K2 + 1):
                    if dp[k1][k2] == INF:
                        continue
                    new_k1 = k1 + x1
                    new_k2 = k2 + x2
                    if new_k1 <= K1 and new_k2 <= K2:
                        if new_dp[new_k1][new_k2] > dp[k1][k2] + x1 * C1 + x2 * C2:
                            new_dp[new_k1][new_k2] = dp[k1][k2] + x1 * C1 + x2 * C2
        # Merge new_dp into dp by taking element-wise minima
        for k1 in range(K1 + 1):
            for k2 in range(K2 + 1):
                if new_dp[k1][k2] < dp[k1][k2]:
                    dp[k1][k2] = new_dp[k1][k2]

    min_cost = INF
    for k1 in range(K1 + 1):
        for k2 in range(K2 + 1):
            if dp[k1][k2] < min_cost:
                min_cost = dp[k1][k2]

    if min_cost == INF:
        print(-1)
    else:
        print(min_cost)

