def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    R = data[1]
    C = data[2]

    # Check if R and C have exactly one A, B, and C
    if sorted(R) != ['A', 'B', 'C'] or sorted(C) != ['A', 'B', 'C']:
        print("No")
        return

    # Initialize the grid
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Function to check if the current grid is valid
    def is_valid():
        # Check rows
        for row in grid:
            chars = [c for c in row if c != '.']
            if sorted(chars) != ['A', 'B', 'C']:
                return False
        # Check columns
        for col in range(N):
            chars = [grid[row][col] for row in range(N) if grid[row][col] != '.']
            if sorted(chars) != ['A', 'B', 'C']:
                return False
        # Check leftmost characters in rows
        for i in range(N):
            for j in range(N):
                if grid[i][j] != '.':
                    if grid[i][j] != R[i]:
                        return False
                    break
        # Check topmost characters in columns
        for j in range(N):
            for i in range(N):
                if grid[i][j] != '.':
                    if grid[i][j] != C[j]:
                        return False
                    break
        return True

    # Backtracking function to fill the grid
    def backtrack(row):
        if row == N:
            if is_valid():
                return True
            return False
        # Get the leftmost character for this row
        left_char = R[row]
        # Try to place left_char in each column
        for col in range(N):
            if grid[row][col] == '.':
                grid[row][col] = left_char
                # Now, try to place the remaining characters in this row
                # We need to place 'A', 'B', 'C' in this row, excluding left_char
                remaining_chars = {'A', 'B', 'C'} - {left_char}
                # Try all permutations of remaining_chars
                from itertools import permutations
                for perm in permutations(remaining_chars):
                    # Fill the row with the permutation
                    idx = 0
                    for j in range(N):
                        if grid[row][j] == '.':
                            grid[row][j] = perm[idx]
                            idx += 1
                    # Check if the current grid is valid
                    if is_valid():
                        # Move to the next row
                        if backtrack(row + 1):
                            return True
                    # Backtrack: reset the row
                    for j in range(N):
                        if j != col:
                            grid[row][j] = '.'
                # Backtrack: reset the left_char
                grid[row][col] = '.'
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print(''.join(row))
    else:
        print("No")

