import sys
from itertools import combinations

class DSU:
    def __init__(self, n):
        self.parent = list(range(n+1))  # 1-based indexing
        self.rank = [0]*(n+1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1
        return True

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    M = int(input[ptr])
    ptr += 1
    K = int(input[ptr])
    ptr += 1

    edges = []
    for _ in range(M):
        u = int(input[ptr])
        v = int(input[ptr+1])
        w = int(input[ptr+2])
        edges.append((u, v, w))
        ptr += 3

    min_cost = K  # Initialize with maximum possible mod value

    # Iterate all possible combinations of N-1 edges
    for candidate in combinations(edges, N-1):
        dsu = DSU(N)
        total = 0
        connected = True
        for u, v, w in candidate:
            if dsu.find(u) != dsu.find(v):
                dsu.union(u, v)
                total += w
            else:
                connected = False
                break
        if connected:
            # Check if all nodes are connected
            root = dsu.find(1)
            all_connected = True
            for i in range(2, N+1):
                if dsu.find(i) != root:
                    all_connected = False
                    break
            if all_connected:
                mod = total % K
                if mod < min_cost:
                    min_cost = mod

    print(min_cost)

