def main():
    D = int(input())
    min_diff = float('inf')
    max_x = int(math.isqrt(D)) + 2
    for x in range(0, max_x):
        x_squared = x * x
        if x_squared > D:
            break
        remaining = D - x_squared
        y = math.isqrt(remaining)
        for dy in [y, y + 1]:
