MOD = 998244353

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    parent = []
    rank = []
    size = 0
    # Flatten the 2D grid into 1D for DSU: index = i * W + j
    size = H * W
    parent = [i for i in range(size)]
    rank = [0] * size

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if rank[u_root] > rank[v_root]:
            parent[v_root] = u_root
        else:
            parent[u_root] = v_root
            if rank[u_root] == rank[v_root]:
                rank[v_root] += 1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Process all green cells and build the initial DSU
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        u = i * W + j
                        v = ni * W + nj
                        union(u, v)

    # Count initial connected components
    initial_components = 0
    roots = set()
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                u = i * W + j
                root = find(u)
                roots.add(root)
    initial_components = len(roots)

    red_cells = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                red_cells.append((i, j))
    K = len(red_cells)
    if K == 0:
        print(0)
        return

    total = 0
    for i, j in red_cells:
        adjacent_roots = set()
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                v = ni * W + nj
                root = find(v)
                adjacent_roots.add(root)
        m = len(adjacent_roots)
        new_components = initial_components + 1 - m
        total += new_components

    # Compute expected value: total / K mod MOD
    inv_K = pow(K, MOD-2, MOD)
    expected = (total % MOD) * inv_K % MOD
    print(expected)

