import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N, M = map(int, input[ptr:ptr+2])
    ptr +=2

    INF = 1 << 60
    dist = [[INF]*(N+1) for _ in range(N+1)]
    for i in range(N+1):
        dist[i][i] = 0

    for _ in range(M):
        u, v, w = map(int, input[ptr:ptr+3])
        ptr +=3
        if dist[u][v] > w:
            dist[u][v] = w

    # Floyd-Warshall to compute all pairs shortest paths
    for k in range(1, N+1):
        for i in range(1, N+1):
            for j in range(1, N+1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Check if the graph is strongly connected (i.e., all pairs have a path)
    strongly_connected = True
    for i in range(1, N+1):
        for j in range(1, N+1):
            if i != j and dist[i][j] == INF:
                strongly_connected = False
                break
        if not strongly_connected:
            break
    if not strongly_connected:
        print("No")
        return

    # DP[mask][u] : minimal cost to reach u with visited set mask
    dp = [[INF]*(N+1) for _ in range(1<<N)]
    for u in range(1, N+1):
        dp[1<<(u-1)][u] = 0

    for mask in range(1<<N):
        for u in range(1, N+1):
            if not (mask & (1<<(u-1))):
                continue
            if dp[mask][u] == INF:
                continue
            for v in range(1, N+1):
                if mask & (1<<(v-1)):
                    continue
                new_mask = mask | (1<<(v-1))
                if dp[new_mask][v] > dp[mask][u] + dist[u][v]:
                    dp[new_mask][v] = dp[mask][u] + dist[u][v]

    full_mask = (1<<N) -1
    res = min(dp[full_mask][u] for u in range(1, N+1))
    if res >= INF:
        print("No")
    else:
        print(res)

