                    if valid:
                        for x in range(i, i + da):
                            for y in range(j, j + db):
                                grid[x][y] = True
                        if backtrack((i + (j + db) // W, (j + db) % W)):
                            return True
                        for x in range(i, i + da):
                            for y in range(j, j + db):
                                grid[x][y] = False
        return False

    if backtrack((0, 0)):
