def main():
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)

    # The game state is represented by a 3x3 grid where 1 is Takahashi (red), -1 is Aoki (blue), 0 is white
    # We'll use minimax to determine the winner

    def check_win(state):
        # Check rows
        for i in range(3):
            if state[i][0] == state[i][1] == state[i][2] != 0:
                return state[i][0]
        # Check columns
        for j in range(3):
            if state[0][j] == state[1][j] == state[2][j] != 0:
                return state[0][j]
        # Check diagonals
        if state[0][0] == state[1][1] == state[2][2] != 0:
            return state[0][0]
        if state[0][2] == state[1][1] == state[2][0] != 0:
            return state[0][2]
        return 0

    def is_full(state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return False
        return True

    def calculate_scores(state):
        t_score = 0
        a_score = 0
        for i in range(3):
            for j in range(3):
                if state[i][j] == 1:
                    t_score += grid[i][j]
                elif state[i][j] == -1:
                    a_score += grid[i][j]
        return (t_score, a_score)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def minimax(state_tuple, is_takahashi_turn):
        state = [list(row) for row in state_tuple]
        winner = check_win(state)
        if winner != 0:
            return winner
        if is_full(state):
            t_score, a_score = calculate_scores(state)
            if t_score > a_score:
                return 1
            else:
                return -1

        if is_takahashi_turn:
            best_value = -2  # -2 represents worse than the worst possible outcome
            for i in range(3):
                for j in range(3):
                    if state[i][j] == 0:
                        new_state = [list(row) for row in state]
                        new_state[i][j] = 1
                        new_state_tuple = tuple(tuple(row) for row in new_state)
                        value = minimax(new_state_tuple, False)
                        if value > best_value:
                            best_value = value
                            if best_value == 1:
                                return 1  # alpha-beta pruning
            return best_value
        else:
            best_value = 2
            for i in range(3):
                for j in range(3):
                    if state[i][j] == 0:
                        new_state = [list(row) for row in state]
                        new_state[i][j] = -1
                        new_state_tuple = tuple(tuple(row) for row in new_state)
                        value = minimax(new_state_tuple, True)
                        if value < best_value:
                            best_value = value
                            if best_value == -1:
                                return -1
            return best_value

    initial_state = ((0, 0, 0), (0, 0, 0), (0, 0, 0))
    result = minimax(initial_state, True)
    if result == 1:
        print("Takahashi")
    else:
        print("Aoki")

