            if grid[i][j] == '.' and not visited[i][j]:
                queue = deque()
                queue.append((i, j))
                visited[i][j] = True
                component_size = 0

                while queue:
                    x, y = queue.popleft()
                    component_size += 1

                    can_move = True
                    # Check adjacent cells for magnets
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if grid[nx][ny] == '#':
                                can_move = False
                                break
                    if not can_move:
