def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx])
    idx += 1
    cards = []
    for _ in range(N):
        a = int(data[idx])
        b = int(data[idx+1])
        cards.append((a, b))
        idx += 2

    # We'll use memoization to store whether a state is winning (1) or losing (0)
    memo = {}

    def dfs(mask):
        if mask in memo:
            return memo[mask]
        # Check all possible pairs of remaining cards
        remaining = []
        for i in range(N):
            if mask & (1 << i):
                remaining.append(i)
        # Try all possible pairs
        can_win = False
        for i in range(len(remaining)):
            for j in range(i + 1, len(remaining)):
                a_i, b_i = cards[remaining[i]]
                a_j, b_j = cards[remaining[j]]
                if a_i == a_j or b_i == b_j:
                    new_mask = mask & ~ (1 << remaining[i]) & ~ (1 << remaining[j])
                    if not dfs(new_mask):
                        can_win = True
                        break
            if can_win:
                break
        memo[mask] = can_win
        return can_win

    initial_mask = (1 << N) - 1
    if dfs(initial_mask):
        print("Takahashi")
    else:
        print("Aoki")

